# --- 1) 타입 수만 바꾼다 ---

$ cat Deopt.java
interface Op { int apply(int x); }
static class A implements Op { public int apply(int x) { return x + 1; } }
static class B implements Op { public int apply(int x) { return x + 2; } }
static class C implements Op { public int apply(int x) { return x + 3; } }

static long run(Op[] ops, int n) {
    long s = 0;
    for (int i = 0; i < n; i++) s += ops[i & (ops.length-1)].apply(i);
    return s;
}

$ for K in 1 2 4; do java -cp out Deopt $K; done
타입 1가지  191 ms
타입 2가지  376 ms
타입 3가지  773 ms

# --- 2) 나중에 타입을 하나 더 넣는다 ---

$ cat Deopt2.java
static Op op = new A();
static long run(int n) { long s = 0; for (int i = 0; i < n; i++) s += op.apply(i); return s; }
public static void main(String[] x) {
    for (int r = 1; r <= 12; r++) {
        if (r == 7) { op = new B(); System.out.println("  --- 여기서 B 를 넣는다 ---"); }
        ... run(30_000_000) 시간 측정 ...
    }
}

$ java -cp out Deopt2
